class _CustomRoleCreateTabState extends State<_CustomRoleCreateTab> {
  final TextEditingController name = TextEditingController();
  final TextEditingController phone = TextEditingController();
  bool saving = false;
  bool loadingApparatus = false;
  bool loadingItemGroups = false;
  List<AdminApparatus> apparatus = const [];
  final Set<String> selectedApparatus = <String>{};
  List<String> itemGroups = const [];
  final Set<String> selectedItemGroups = <String>{};

  bool get _isAparatchiRole => widget.assignedRole.id == 'aparatchi';
  bool get _isQolipchiRole => widget.assignedRole.id == 'qolipchi';
  bool get _isBoyoqchiRole => widget.assignedRole.id == 'boyoqchi';
  bool get _isMaterialTaminotchiAssignedRole =>
      _isMaterialTaminotchiRole(widget.assignedRole);

  @override
  void initState() {
    super.initState();
    if (_isAparatchiRole) {
      unawaited(_loadApparatus());
    }
    if (_isMaterialTaminotchiAssignedRole) {
      unawaited(_loadItemGroups());
    }
  }

  Future<void> _loadApparatus() async {
    setState(() => loadingApparatus = true);
    try {
      final items = await MobileApi.instance.adminApparatus(limit: 200);
      if (!mounted) {
        return;
      }
      setState(() {
        apparatus = items;
        loadingApparatus = false;
      });
    } catch (_) {
      if (mounted) {
        setState(() => loadingApparatus = false);
      }
    }
  }

  Future<void> _loadItemGroups() async {
    setState(() => loadingItemGroups = true);
    try {
      final groups = await MobileApi.instance.adminItemGroups();
      if (!mounted) {
        return;
      }
      setState(() {
        itemGroups = _normalizedItemGroups(groups);
        loadingItemGroups = false;
      });
    } catch (_) {
      if (mounted) {
        setState(() => loadingItemGroups = false);
      }
    }
  }

  @override
  void dispose() {
    name.dispose();
    phone.dispose();
    super.dispose();
  }

  Future<void> _create() async {
    if (_isAparatchiRole && selectedApparatus.isEmpty) {
      showAdminTopNotice(
        context,
        context.l10n.adminText('user.minimum_apparatus'),
      );
      return;
    }
    if (_isMaterialTaminotchiAssignedRole && selectedItemGroups.isEmpty) {
      showAdminTopNotice(
        context,
        context.l10n.adminText('user.minimum_item_group'),
      );
      return;
    }
    setState(() => saving = true);
    try {
      if (_isQolipchiRole || _isBoyoqchiRole) {
        final role = _isBoyoqchiRole ? UserRole.boyoqchi : UserRole.qolipchi;
        final user = await MobileApi.instance.adminCreateSystemUser(
          role: role,
          name: name.text.trim(),
          phone: phone.text.trim(),
        );
        await MobileApi.instance.adminRegenerateSystemUserCode(user.id);
      } else if (_isMaterialTaminotchiAssignedRole) {
        await MobileApi.instance.adminCreateMaterialTaminotchi(
          name: name.text.trim(),
          phone: phone.text.trim(),
          assignedItemGroups: _sortedSelection(selectedItemGroups),
        );
      } else {
        final user = await MobileApi.instance.adminCreateCustomer(
          name: name.text.trim(),
          phone: phone.text.trim(),
        );
        if (_isAparatchiRole) {
          await MobileApi.instance.adminUpsertRoleAssignment(
            adminAparatchiAssignmentUpsert(
              principalRef: user.ref,
              assignedApparatus: selectedApparatus.toList(growable: false)
                ..sort(),
            ),
          );
          await MobileApi.instance.adminRegenerateCustomerCode(user.ref);
        } else {
          final principalRole = _principalRoleForAssignedRole(
            widget.assignedRole,
          );
          await _assignCustomRole(
            widget.assignedRole,
            principalRole,
            user.ref,
          );
        }
      }
      if (!mounted) {
        return;
      }
      name.clear();
      phone.clear();
      selectedApparatus.clear();
      selectedItemGroups.clear();
      AdminSuppliersScreen.invalidateCache();
      showAdminTopNotice(
        context,
        context.l10n.adminText('user.created'),
      );
    } catch (error) {
      if (mounted) {
        showAdminTopNotice(
          context,
          _adminCreateErrorMessage(error, context.l10n),
        );
      }
    } finally {
      if (mounted) {
        setState(() => saving = false);
      }
    }
  }

  Future<void> _openItemGroupPicker() async {
    if (loadingItemGroups) {
      return;
    }
    if (itemGroups.isEmpty) {
      await _loadItemGroups();
      if (!mounted || itemGroups.isEmpty) {
        return;
      }
    }
    final picked = await showGeneralDialog<Set<String>>(
      context: context,
      useRootNavigator: true,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.black.withValues(alpha: 0.32),
      transitionDuration: const Duration(milliseconds: 240),
      pageBuilder: (context, animation, secondaryAnimation) {
        return _MaterialItemGroupPickerSheet(
          itemGroups: itemGroups,
          selectedGroups: selectedItemGroups,
        );
      },
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
          reverseCurve: Curves.easeInCubic,
        );
        return FadeTransition(opacity: curved, child: child);
      },
    );
    if (picked == null || !mounted) {
      return;
    }
    setState(() {
      selectedItemGroups
        ..clear()
        ..addAll(_sortedSelection(picked));
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(12, 8, 12, 0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              TextField(
                controller: name,
                textInputAction: TextInputAction.next,
                decoration: appSoftInputDecoration(
                  context,
                  labelText: context.l10n.adminText('user.name'),
                ),
              ),
              const SizedBox(height: _adminUserCreateFieldGap),
              TextField(
                controller: phone,
                keyboardType: TextInputType.phone,
                decoration: appSoftInputDecoration(
                  context,
                  labelText: context.l10n.adminText('user.phone'),
                ),
              ),
              if (_isAparatchiRole) ...[
                const SizedBox(height: 16),
                if (loadingApparatus)
                  const Center(child: AppLoadingIndicator())
                else
                  AdminApparatusScopePicker(
                    apparatus: apparatus,
                    selected: selectedApparatus,
                    onChanged: (apparatusId, checked) {
                      setState(() {
                        if (checked) {
                          selectedApparatus.add(apparatusId);
                        } else {
                          selectedApparatus.remove(apparatusId);
                        }
                      });
                    },
                  ),
              ],
              if (_isMaterialTaminotchiAssignedRole) ...[
                const SizedBox(height: 16),
                _MaterialItemGroupScopeSelector(
                  loading: loadingItemGroups,
                  selectedGroups: _sortedSelection(selectedItemGroups),
                  onTap: _openItemGroupPicker,
                ),
              ],
            ],
          ),
        ),
        Padding(
          padding: _adminUserCreatePagePadding,
          child: FilledButton(
            onPressed: saving ||
                    (_isMaterialTaminotchiAssignedRole &&
                        selectedItemGroups.isEmpty)
                ? null
                : _create,
            child: Text(
              saving
                  ? context.l10n.adminText('user.saving')
